        "functionCode": "const modeRaw = String($json.stdout || $json.bot_mode_srv2 || '').trim().toLowerCase();\nconst bot_mode_srv2 = (modeRaw === 'stop') ? 'stop' : 'start';\n\n// - pre: item de \"Set is_audio (pre-memory)\" con __is_audio / is_audio_i / message_type\nconst triggerItem = ($node[\"WAHA Webhook In\"] && $node[\"WAHA Webhook In\"].json) ? $node[\"WAHA Webhook In\"].json : {};\nconst pre = ($node[\"Set is_audio (pre-memory)\"] && $node[\"Set is_audio (pre-memory)\"].json) ? $node[\"Set is_audio (pre-memory)\"].json : {};\n\n// Mezcla: mantenemos el evento real (triggerItem) pero conservamos los flags ya calculados (pre)\nreturn [{\n  ...triggerItem,\n  ...pre,\n  bot_mode_srv2\n}];"
