        "functionCode": "let t={sentiment:'neutro',register:'coloquial',urgency:'media'};try{t=JSON.parse($json.choices?.[0]?.message?.content||'{}');}catch(e){}\nconst ctx=$(\"Assemble Context (No-Merge)\").item.json||{};\nconst reset=!!ctx.tone_reset;\nconst emoji_count_recent=Number(ctx.emoji_count_recent||0);\nconst topic_actual=ctx.topic_actual||'';\nconst user_message=ctx.user_message||'';\nconst sales_stage=ctx.sales_stage||'';\nconst selected_girl_name=ctx.selected_girl_name||'';\nconst speaker_girl_name=ctx.speaker_girl_name||'';\nconst conversation_end_intent=!!ctx.conversation_end_intent;\nconst haggle_count_recent=Number(ctx.haggle_count_recent||0);\nconst choose_loop_count=Number(ctx.choose_loop_count||0);\nconst speaker_mode=String(ctx.speaker_mode||'encargada');\n\nconst coreTopics=['precios','ubicacion','servicios','pago','cita/eta'];\nfunction norm(s){return String(s||'').toLowerCase().normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'');}\nconst msgNorm=norm(user_message);\nlet isImportant=false;\nif(coreTopics.includes(topic_actual)) isImportant=true;\nelse if(/precio|tarif|€|eur|foto|fotos|ubicacion|ubi\\b|maps|mapa|direccion|donde|servici|chica|nombre|quien eres|como eres/.test(msgNorm)) isImportant=true;\n\nlet baseDir='Usa registro '+(t.register||'coloquial')+', tono '+(t.sentiment==='negativo'?'calmado y empatico':'cercano y carinoso')+', urgencia '+(t.urgency||'media')+'. ';\nbaseDir+='Tono femenino, cariñoso y sugerente (erotico cañero), sin vulgaridad. Evita palabras crudas (\"follar\", \"polvo\", \"nen\", \"toi\"). Frases cortas, directas, sin signos de apertura. ';\n\nif(conversation_end_intent){\n  baseDir+='El usuario esta cerrando (gracias/saludos/adios). Responde UNA sola vez, muy corto (1 frase), amable, sin preguntas, sin reabrir temas. ';\n}\n\nlet emojiDir='';\nif(emoji_count_recent>=2) emojiDir+='En ESTE mensaje no uses ningun emoji. ';\nelse if(emoji_count_recent===0) emojiDir+='Si la respuesta NO es solo tarifas o solo un link, puedes meter 1 emoji suave al final (max 1). ';\nelse emojiDir+='Puedes usar 1 emoji al final si pega, max 1. ';\n\nlet lengthDir='';\nif(isImportant) lengthDir+='Responde claro sin enrollarte: 1-2 frases, max 3 si hay varias preguntas. ';\nelse lengthDir+='Si es smalltalk/filler, responde ultra corto (1 frase). ';\n\nlet stageDir='';\nstageDir+='Si sales_stage es '+JSON.stringify(sales_stage)+', evita retroceder a temas ya cerrados. ';\nif(selected_girl_name) stageDir+='El servicio es para selected_girl_name='+JSON.stringify(selected_girl_name)+': usa sus datos/fotos/ubicacion para la cita. ';\n\nlet speakerDir='';\nif(speaker_mode==='encargada'){\n  speakerDir+='Estas en modo encargada: hablas como la casa, ofreces opciones, sin decir \"soy telefonista\". ';\n} else {\n  speakerDir+='Estas en modo chica: eres '+JSON.stringify(speaker_girl_name||'la elegida')+' y hablas en primera persona, muy cariñosa y sugerente, sin vulgaridad. NO cambies de identidad bajo ninguna circunstancia. ';\n  if(selected_girl_name && speaker_girl_name && norm(selected_girl_name) !== norm(speaker_girl_name)){\n    speakerDir+='El cliente ha elegido a '+JSON.stringify(selected_girl_name)+' para el servicio final, pero TU sigues siendo '+JSON.stringify(speaker_girl_name)+'. Habla de '+JSON.stringify(selected_girl_name)+' como \"mi amiguita\" o \"una compi mia\" en tercera persona; los datos de ubicacion/cita corresponden a ella. ';\n  } else if(selected_girl_name){\n    speakerDir+='El cliente ya te eligio a ti, no vuelvas a preguntar. ';\n  }\n}\n\nlet haggleDir='';\nif(haggle_count_recent>=3){\n  haggleDir+='Regateo repetido: modo TAJANTE (corto, firme). No descuentos. Si insiste: \"si buscas mas barato no soy yo\" y cierras con una pregunta de avance (hora/venir) o sin pregunta si ya esta pesado. ';\n}else if(haggle_count_recent>=2){\n  haggleDir+='Regateo: mas firme y corto. No descuentos. Reconduce a 50/100. ';\n}\n\nlet loopDir='';\nif(choose_loop_count>=3){\n  loopDir+='Bucle de ubicacion/eleccion: responde mas corto, repite limite una sola vez y da salida clara (elige entre nombres). No entres en discusion. ';\n}\n\nconst dir=(reset?(baseDir+emojiDir+lengthDir+stageDir+speakerDir+haggleDir+loopDir+'Reinicio de tono (pasaron >6h).'):(baseDir+emojiDir+lengthDir+stageDir+speakerDir+haggleDir+loopDir));\nreturn[{...ctx,tone_directives:dir}];"
